  "inlineSchema": "// Kanban boards: columns with WIP limits, tasks with fractional ordering, sprints, epics, labels,\n// comments, attachments, time tracking and an activity log. Lives in its own Postgres schema (\"kanban\").\n// Who may do what is decided by the owning project (project-service); this service stores no roles.\n\ngenerator client {\n  provider      = \"prisma-client-js\"\n  output        = \"../src/generated/client\"\n  binaryTargets = [\"native\", \"debian-openssl-3.0.x\", \"linux-musl-openssl-3.0.x\"]\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"KANBAN_DATABASE_URL\")\n}\n\nenum BoardVisibility {\n  PRIVATE\n  PUBLIC\n}\n\nenum TaskType {\n  TASK\n  STORY\n  BUG\n  SUBTASK\n}\n\nenum Priority {\n  LOWEST\n  LOW\n  MEDIUM\n  HIGH\n  HIGHEST\n}\n\nenum TaskStatus {\n  TODO\n  IN_PROGRESS\n  IN_REVIEW\n  DONE\n  BLOCKED\n}\n\nenum SprintStatus {\n  PLANNED\n  ACTIVE\n  COMPLETED\n}\n\nmodel UserRef {\n  id        String   @id\n  name      String\n  avatar    String?\n  updatedAt DateTime @updatedAt\n}\n\nmodel Board {\n  id          String          @id @default(uuid())\n  projectId   String\n  name        String\n  description String?\n  /// short prefix for task keys, e.g. \"WEB\" gives WEB-1, WEB-2\n  keyPrefix   String\n  /// last task number handed out; incremented atomically so keys never collide\n  lastNumber  Int             @default(0)\n  visibility  BoardVisibility @default(PRIVATE)\n  createdBy   String\n  archived    Boolean         @default(false)\n  createdAt   DateTime        @default(now())\n  updatedAt   DateTime        @updatedAt\n\n  columns  Column[]\n  tasks    Task[]\n  sprints  Sprint[]\n  epics    Epic[]\n  labels   Label[]\n  activity Activity[]\n\n  @@index([projectId])\n}\n\nmodel Column {\n  id        String     @id @default(uuid())\n  boardId   String\n  name      String\n  color     String     @default(\"#6b7280\")\n  /// moving a task into this column sets the task to this status\n  status    TaskStatus @default(TODO)\n  order     Float\n  /// work-in-progress limit; null means unlimited\n  wipLimit  Int?\n  createdAt DateTime   @default(now())\n\n  board Board  @relation(fields: [boardId], references: [id], onDelete: Cascade)\n  tasks Task[]\n\n  @@index([boardId, order])\n}\n\nmodel Task {\n  id             String     @id @default(uuid())\n  boardId        String\n  columnId       String\n  sprintId       String?\n  epicId         String?\n  parentId       String?\n  number         Int\n  key            String\n  title          String\n  description    String?\n  type           TaskType   @default(TASK)\n  priority       Priority   @default(MEDIUM)\n  status         TaskStatus @default(TODO)\n  points         Int?\n  estimatedHours Float?\n  /// fractional position inside the column: moving a card only rewrites that one card\n  order          Float\n  dueDate        DateTime?\n  completedAt    DateTime?\n  assigneeId     String?\n  reporterId     String\n  createdAt      DateTime   @default(now())\n  updatedAt      DateTime   @updatedAt\n\n  board       Board         @relation(fields: [boardId], references: [id], onDelete: Cascade)\n  column      Column        @relation(fields: [columnId], references: [id])\n  sprint      Sprint?       @relation(fields: [sprintId], references: [id], onDelete: SetNull)\n  epic        Epic?         @relation(fields: [epicId], references: [id], onDelete: SetNull)\n  parent      Task?         @relation(\"Subtasks\", fields: [parentId], references: [id], onDelete: Cascade)\n  subtasks    Task[]        @relation(\"Subtasks\")\n  labels      TaskLabel[]\n  comments    Comment[]\n  attachments Attachment[]\n  timeEntries TimeEntry[]\n  watchers    TaskWatcher[]\n\n  @@unique([boardId, number])\n  @@index([boardId, columnId, order])\n  @@index([assigneeId])\n  @@index([sprintId])\n  @@index([epicId])\n  @@index([parentId])\n}\n\nmodel Sprint {\n  id              String       @id @default(uuid())\n  boardId         String\n  name            String\n  goal            String?\n  startDate       DateTime\n  endDate         DateTime\n  status          SprintStatus @default(PLANNED)\n  committedPoints Int?\n  completedPoints Int?\n  startedAt       DateTime?\n  completedAt     DateTime?\n  createdAt       DateTime     @default(now())\n\n  board Board  @relation(fields: [boardId], references: [id], onDelete: Cascade)\n  tasks Task[]\n\n  @@index([boardId, status])\n}\n\nmodel Epic {\n  id          String   @id @default(uuid())\n  boardId     String\n  name        String\n  description String?\n  color       String   @default(\"#7c3aed\")\n  createdAt   DateTime @default(now())\n\n  board Board  @relation(fields: [boardId], references: [id], onDelete: Cascade)\n  tasks Task[]\n\n  @@index([boardId])\n}\n\nmodel Label {\n  id        String   @id @default(uuid())\n  boardId   String\n  name      String\n  color     String\n  createdAt DateTime @default(now())\n\n  board Board       @relation(fields: [boardId], references: [id], onDelete: Cascade)\n  tasks TaskLabel[]\n\n  @@unique([boardId, name])\n}\n\nmodel TaskLabel {\n  taskId  String\n  labelId String\n\n  task  Task  @relation(fields: [taskId], references: [id], onDelete: Cascade)\n  label Label @relation(fields: [labelId], references: [id], onDelete: Cascade)\n\n  @@id([taskId, labelId])\n  @@index([labelId])\n}\n\nmodel Comment {\n  id        String   @id @default(uuid())\n  taskId    String\n  userId    String\n  content   String\n  mentions  String[]\n  edited    Boolean  @default(false)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  task Task @relation(fields: [taskId], references: [id], onDelete: Cascade)\n\n  @@index([taskId, createdAt])\n}\n\n/// An attachment: the bytes live in the file-service.\nmodel Attachment {\n  id        String   @id @default(uuid())\n  taskId    String\n  fileId    String\n  name      String\n  mimeType  String\n  size      Int\n  addedBy   String\n  createdAt DateTime @default(now())\n\n  task Task @relation(fields: [taskId], references: [id], onDelete: Cascade)\n\n  @@unique([taskId, fileId])\n}\n\nmodel TimeEntry {\n  id          String   @id @default(uuid())\n  taskId      String\n  userId      String\n  hours       Float\n  description String?\n  date        DateTime\n  createdAt   DateTime @default(now())\n\n  task Task @relation(fields: [taskId], references: [id], onDelete: Cascade)\n\n  @@index([taskId])\n  @@index([userId, date])\n}\n\nmodel TaskWatcher {\n  taskId String\n  userId String\n\n  task Task @relation(fields: [taskId], references: [id], onDelete: Cascade)\n\n  @@id([taskId, userId])\n  @@index([userId])\n}\n\nmodel Activity {\n  id        String   @id @default(uuid())\n  boardId   String\n  taskId    String?\n  userId    String\n  action    String\n  /// what changed, e.g. { field: \"assignee\", from: \"...\", to: \"...\" }\n  detail    Json     @default(\"{}\")\n  createdAt DateTime @default(now())\n\n  board Board @relation(fields: [boardId], references: [id], onDelete: Cascade)\n\n  @@index([boardId, createdAt])\n  @@index([taskId, createdAt])\n}\n",
